SilikoValue CustomFunctionAddTwo(int ArgC, SilikoValue *ArgV)
{
    SilikoValue ReturnValue;
    if (ArgC != 1)
    {
        ReturnValue.Status = SILIKO_VAL_BAD_ARGUMENTS;
        ReturnValue.Integer = 0;
        return ReturnValue;
    }

    ReturnValue.Status = ArgV[0].Status;
    switch (ArgV[0].Status)
    {
    case SILIKO_VAL_INTEGER:
        ReturnValue.Integer = ArgV[0].Integer + 2;
        break;
    case SILIKO_VAL_FLOAT:
        ReturnValue.Float = Argv[0].Float + 2.0;
        break;
    default: // This is an error. Propagate it.
        ReturnValue.Integer = ArgV[0].Integer;
    }
    return ReturnValue;
}

#include <stdio.h>

#include <SilikoCore/FunctionCaller.h>
#include <SilikoCore/Value.h>

SilikoValue CustomFunctionAddTwo(int ArgC, SilikoValue *ArgV);

int main(int argc, char *argv[])
{
    SilikoFunctionCallerNew *caller();
    SilikoFunctionCallerInstall(caller, "addtwo", CustomFunctionAddTwo);
    SilikoValue inputs[1];
    inputs[0].Status = SILIKO_VAL_INTEGER;
    inputs[0].Integer = 5;
    SilikoValue result = SilikoFunctionCallerCall(caller, "addtwo", 1, inputs);
    char *resultString = SilikoValueToString(result);
    printf("The result is: %s\n", resultString);
    SilikoValueDeleteString(resultString);
    SilikoFunctionCallerDelete();
}

